practice.solution:
const text = stdin.replace(/\r/g, '');
const sep = text.indexOf('\n\n');
const head = sep === -1 ? text.trim() : text.slice(0, sep);
const body = sep === -1 ? '' : text.slice(sep + 2).replace(/\n+$/, '');
const lines = head.split('\n');
const [method, target, version] = lines[0].trim().split(' ');

const headers = {};
for (const line of lines.slice(1)) {
  const i = line.indexOf(':');
  if (i === -1) continue;
  headers[line.slice(0, i).trim().toLowerCase()] = line.slice(i + 1).trim();
}

const q = target.indexOf('?');
const path = q === -1 ? target : target.slice(0, q);
const query = q === -1 ? '' : target.slice(q + 1);
const decode = s => decodeURIComponent(s.replace(/\+/g, ' '));
const pairs = query.split('&').filter(Boolean).map(part => {
  const eq = part.indexOf('=');
  const key = eq === -1 ? part : part.slice(0, eq);
  const value = eq === -1 ? '' : part.slice(eq + 1);
  return decode(key) + '=' + decode(value);
});

const conn = (headers.connection || '').toLowerCase();
let keepAlive = version !== 'HTTP/1.0';
if (conn === 'close') keepAlive = false;
if (conn === 'keep-alive') keepAlive = true;

console.log('Method: ' + method.toUpperCase());
console.log('Path: ' + path);
console.log('Query: ' + (pairs.length ? pairs.join(', ') : '(none)'));
console.log('Host: ' + (headers.host || '(missing)'));
console.log('Connection: ' + (keepAlive ? 'keep-alive' : 'close'));
console.log('Body length: ' + body.length);
